#include <iostream>

// User-defined manipulator emitting a tab delimiter
std::ostream& tab(std::ostream& os) {
    return os << '\t';
}

// User-defined manipulator emitting newline and flushing buffer
std::ostream& endLine(std::ostream& os) {
    return os << '\n' << std::flush;
}

int main() {
    std::cout << "Custom manipulators:" << endLine;
    std::cout << 'a' << tab << 'b' << tab << 'c' << endLine;

    std::cout << "Default float representation:" << endLine;
    std::cout << 9.9900 << tab << 9.9000 << tab << 9.0000 << endLine;

    std::cout << "After std::showpoint:" << endLine;
    std::cout << std::showpoint;
    std::cout << 9.9900 << tab << 9.9000 << tab << 9.0000 << endLine;

    std::cout << std::noshowpoint;
    std::cout << "After std::noshowpoint:" << endLine;
    std::cout << 9.9000 << endLine;

    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    int val = 12345;
    int signedVal = 123;

    std::cout << "Right justified (default):\n"
              << "[" << std::setw(10) << val << "]\n\n";

    std::cout << "Left justified:\n"
              << "[" << std::left << std::setw(10) << val << "]\n\n";

    std::cout << "Right justified explicit:\n"
              << "[" << std::right << std::setw(10) << val << "]\n\n";

    std::cout << "Internal justified with showpos:\n"
              << "[" << std::internal << std::showpos << std::setw(10) << signedVal << "]\n\n";

    std::cout << "Reset showpos, still internal:\n"
              << "[" << std::noshowpos << std::setw(10) << -signedVal << "]\n";

    return 0;
}
